#include <catch2/catch_all.hpp>

#include "slic3r/GUI/JusPrin/Home/OrcaImport.hpp"

#include <chrono>
#include <fstream>
#include <set>
#include <thread>

#include <nlohmann/json.hpp>

using namespace Slic3r::GUI::JusPrin::Home;
namespace fs = std::filesystem;
using Kind    = OrcaImportItem::Kind;
using Outcome = OrcaImportItem::Outcome;
using Reason  = OrcaImportItem::Reason;

namespace {

// A folder of its own under the system's temp folder, removed afterwards.
struct TempFolder
{
    fs::path path;
    TempFolder()
    {
        path = fs::temp_directory_path() /
               ("jusprin-orca-import-" + std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));
        fs::create_directories(path);
    }
    ~TempFolder() { fs::remove_all(path); }
};

std::string write(const fs::path& file, const std::string& text)
{
    fs::create_directories(file.parent_path());
    std::ofstream(file) << text;
    return file.u8string();
}

std::string preset(const fs::path& file, const nlohmann::json& json) { return write(file, json.dump()); }

nlohmann::json printer(const std::string& name, const std::string& base = "Bambu Lab X1 Carbon 0.4 nozzle")
{
    return {{"name", name}, {"version", "2.3.0.4"}, {"printer_settings_id", name}, {"inherits", base}};
}

std::string text_of(const std::string& file)
{
    std::ifstream stream(file);
    return {std::istreambuf_iterator<char>(stream), std::istreambuf_iterator<char>()};
}

} // namespace

TEST_CASE("an orca import keeps each file's reason and renames what JusPrin already has", "[home][onboarding][orca_import]")
{
    TempFolder orca, staging;
    const fs::path account = orca.path / "user" / "default";
    const std::string mine     = preset(account / "machine" / "My X1C.json", printer("My X1C"));
    const std::string taken    = preset(account / "machine" / "Shop X1C.json", printer("Shop X1C"));
    const std::string orphan   = preset(account / "machine" / "Old.json", printer("Old", "Some Retired Printer"));
    const std::string broken   = write(account / "filament" / "Broken PLA.json", "{ not json");
    const std::string no_ver   = preset(account / "filament" / "Unversioned.json",
                                        {{"name", "Unversioned"}, {"filament_settings_id", "Unversioned"}});
    const std::string not_one  = preset(account / "process" / "Notes.json", {{"name", "Notes"}, {"version", "1"}});
    const std::string original = text_of(taken);

    std::set<std::string> base_lookups;
    OrcaImportCatalog catalog;
    catalog.has      = [](Kind kind, const std::string& name) { return kind == Kind::Printer && name == "Shop X1C"; };
    catalog.has_base = [&](Kind, const std::string& base) {
        base_lookups.insert(base);
        return base == "Bambu Lab X1 Carbon 0.4 nozzle";
    };

    std::vector<OrcaImportItem> items = plan_orca_import({mine, taken, orphan, broken, no_ver, not_one}, catalog, staging.path);
    REQUIRE(items.size() == 6);

    CHECK(items[0].name == "My X1C");
    CHECK(items[0].outcome == Outcome::Pending);
    CHECK(items[0].file == mine);
    CHECK(items[0].renamed_to.empty());

    // Taken: imported from a renamed copy in the staging folder.
    CHECK(items[1].outcome == Outcome::Pending);
    CHECK(items[1].renamed_to == "Shop X1C (Orca copy)");
    CHECK(items[1].source == taken);
    REQUIRE(fs::path(items[1].file).parent_path() == staging.path);
    const nlohmann::json copy = nlohmann::json::parse(text_of(items[1].file));
    CHECK(copy["name"] == "Shop X1C (Orca copy)");
    CHECK(copy["printer_settings_id"] == "Shop X1C (Orca copy)");
    CHECK(copy["inherits"] == "Bambu Lab X1 Carbon 0.4 nozzle");
    // OrcaSlicer's own file is only read.
    CHECK(text_of(taken) == original);

    CHECK(items[2].outcome == Outcome::NotImported);
    CHECK(items[2].reason == Reason::MissingBase);
    CHECK(items[2].base == "Some Retired Printer");

    CHECK(items[3].kind == Kind::Filament);
    CHECK(items[3].name == "Broken PLA");
    CHECK(items[3].reason == Reason::Unreadable);
    CHECK(items[4].reason == Reason::NoVersion);
    CHECK(items[5].kind == Kind::Process);
    CHECK(items[5].reason == Reason::NotAPreset);
    CHECK(base_lookups.count("Some Retired Printer") == 1);

    SECTION("import_presets' answer settles the rest")
    {
        // It imported the renamed copy but not "My X1C".
        settle_orca_import(items, {items[1].file});
        CHECK(items[0].outcome == Outcome::NotImported);
        CHECK(items[0].reason == Reason::NotLoaded);
        CHECK(items[1].outcome == Outcome::Imported);
        // A reason found before the import stays.
        CHECK(items[2].reason == Reason::MissingBase);
    }
}

TEST_CASE("an orca import numbers a second copy and finds bases among its own files", "[home][onboarding][orca_import]")
{
    TempFolder orca, staging;
    const fs::path filaments = orca.path / "user" / "default" / "filament";
    const auto filament = [&](const std::string& name, const std::string& base) {
        return preset(filaments / (name + ".json"),
                      {{"name", name}, {"version", "1.0"}, {"filament_settings_id", name}, {"inherits", base}});
    };
    const std::string base  = filament("My Base PLA", "Generic PLA @System");
    const std::string child = filament("My PLA", "My Base PLA");

    OrcaImportCatalog catalog;
    // JusPrin has "My PLA" and already a first copy of it.
    catalog.has      = [](Kind, const std::string& name) { return name == "My PLA" || name == "My PLA (Orca copy)"; };
    catalog.has_base = [](Kind, const std::string& name) { return name == "Generic PLA @System"; };

    const std::vector<OrcaImportItem> items = plan_orca_import({base, child}, catalog, staging.path);
    CHECK(items[0].outcome == Outcome::Pending);
    CHECK(items[1].outcome == Outcome::Pending);
    CHECK(items[1].renamed_to == "My PLA (Orca copy 2)");
    CHECK(nlohmann::json::parse(text_of(items[1].file))["filament_settings_id"] == "My PLA (Orca copy 2)");
}

TEST_CASE("an orca account folder is found from what the person picks", "[home][onboarding][orca_import]")
{
    TempFolder orca;
    const fs::path root = orca.path / "OrcaSlicer";
    preset(root / "user" / "default" / "machine" / "Old.json", printer("Old"));
    // Saved later, under a Bambu account's id.
    std::this_thread::sleep_for(std::chrono::milliseconds(20));
    preset(root / "user" / "1234" / "machine" / "New.json", printer("New"));
    const fs::path account = root / "user" / "1234";

    CHECK(orca_account_folder(root) == account);
    CHECK(orca_account_folder_for_pick(root) == account);
    CHECK(orca_account_folder_for_pick(root / "user") == account);
    CHECK(orca_account_folder_for_pick(account) == account);
    CHECK(orca_account_folder_for_pick(account / "machine") == account);
    CHECK_FALSE(orca_account_folder_for_pick(orca.path).has_value());

    const OrcaPresetFiles presets = scan_orca_presets(account);
    CHECK(presets.printers == std::vector<std::string>{"New"});
    CHECK(presets.files.size() == 1);

    SECTION("OrcaSlicer.conf names the account, after its JSON a checksum line")
    {
        write(root / "OrcaSlicer.conf", R"({"app": {"preset_folder": "default"}})" "\n# MD5 checksum 0123\n");
        CHECK(orca_account_folder(root) == root / "user" / "default");
    }
    SECTION("an unreadable OrcaSlicer.conf names nothing")
    {
        write(root / "OrcaSlicer.conf", "{ broken");
        CHECK_FALSE(orca_account_folder(root).has_value());
    }
}

#include <catch2/catch_all.hpp>

#include "slic3r/GUI/JusPrin/Home/OnboardingModel.hpp"

using namespace Slic3r::GUI::JusPrin::Home;

TEST_CASE("a first launch runs welcome, then printers, then home", "[home][onboarding]")
{
    OnboardingProgress progress;
    OnboardingFacts facts;
    CHECK(next_onboarding_step(progress, facts) == OnboardingStep::Welcome);

    // Any door, "Just slice for now" included, leaves the welcome.
    progress.welcome_left = true;
    CHECK(next_onboarding_step(progress, facts) == OnboardingStep::Printers);

    progress.printer_chosen = true;
    CHECK(next_onboarding_step(progress, facts) == OnboardingStep::Hidden);
}

TEST_CASE("back from printers returns to the welcome", "[home][onboarding]")
{
    OnboardingProgress progress;
    OnboardingFacts facts;
    progress.welcome_left = true;
    REQUIRE(next_onboarding_step(progress, facts) == OnboardingStep::Printers);
    progress.welcome_left = false;
    CHECK(next_onboarding_step(progress, facts) == OnboardingStep::Welcome);
}

TEST_CASE("the welcome shows once even with something already set up", "[home][onboarding]")
{
    OnboardingProgress progress;
    OnboardingFacts facts;
    facts.v1_imported       = true;
    facts.printer_from_file = true;
    facts.orca_printers     = true;
    CHECK(next_onboarding_step(progress, facts) == OnboardingStep::Welcome);
}

TEST_CASE("a v1 import or a file's printer skips the printers step", "[home][onboarding]")
{
    OnboardingProgress progress;
    progress.welcome_left = true;

    OnboardingFacts v1;
    v1.v1_imported = true;
    CHECK(next_onboarding_step(progress, v1) == OnboardingStep::Hidden);

    OnboardingFacts file;
    file.printer_from_file = true;
    CHECK(next_onboarding_step(progress, file) == OnboardingStep::Hidden);
}

TEST_CASE("completed onboarding never shows again", "[home][onboarding]")
{
    OnboardingProgress progress;
    progress.status = OnboardingStatus::Completed;
    CHECK(next_onboarding_step(progress, OnboardingFacts{}) == OnboardingStep::Hidden);
}

TEST_CASE("the printers step offers OrcaSlicer's printers until start fresh", "[home][onboarding]")
{
    OnboardingProgress progress;
    OnboardingFacts facts;
    CHECK(printers_screen(progress, facts) == PrintersScreen::AddPrinter);

    facts.orca_printers = true;
    CHECK(printers_screen(progress, facts) == PrintersScreen::OrcaImport);

    progress.fresh_start = true;
    CHECK(printers_screen(progress, facts) == PrintersScreen::AddPrinter);
}

TEST_CASE("an import's result holds the printers step until continue", "[home][onboarding]")
{
    OnboardingProgress progress;
    progress.welcome_left = true;
    OnboardingFacts facts;
    facts.orca_printers      = true;
    facts.import_result_open = true;
    // The import brought a printer, which alone would end the sequence.
    progress.printer_chosen = true;
    CHECK(next_onboarding_step(progress, facts) == OnboardingStep::Printers);
    CHECK(printers_screen(progress, facts) == PrintersScreen::ImportResult);

    facts.import_result_open = false;
    CHECK(next_onboarding_step(progress, facts) == OnboardingStep::Hidden);
}

TEST_CASE("home's agent group follows the agent's setup", "[home][onboarding]")
{
    CHECK(home_agent_card(false, false, false) == HomeAgentCard::Doors);
    // Signed in: the account and its credits, once.
    CHECK(home_agent_card(true, true, false) == HomeAgentCard::Account);
    CHECK(home_agent_card(true, true, true) == HomeAgentCard::None);
    // Your own key or an AI tool: nothing to show.
    CHECK(home_agent_card(true, false, false) == HomeAgentCard::None);
}

#include "OrcaImport.hpp"

#include <algorithm>
#include <fstream>
#include <set>
#include <stdexcept>

#include <nlohmann/json.hpp>

namespace Slic3r::GUI::JusPrin::Home {

namespace fs = std::filesystem;

namespace {

// OrcaSlicer's own names (Preset.hpp, PresetBundle.hpp), repeated here so
// this file needs no libslic3r.
const char* const kUserFolder    = "user";     // PRESET_USER_DIR
const char* const kDefaultFolder = "default";  // DEFAULT_USER_FOLDER_NAME
const char* const kPrinterFolder = "machine";  // PRESET_PRINTER_NAME
const char* const kFilamentFolder = "filament"; // PRESET_FILAMENT_NAME
const char* const kProcessFolder = "process";  // PRESET_PRINT_NAME

using Kind = OrcaImportItem::Kind;

Kind kind_of_folder(const fs::path& file)
{
    const std::string folder = file.parent_path().filename().u8string();
    return folder == kFilamentFolder ? Kind::Filament : folder == kProcessFolder ? Kind::Process : Kind::Printer;
}

// The key import_json_presets tells the kinds apart by, which also holds
// the preset's name.
const char* settings_id_key(Kind kind)
{
    switch (kind) {
    case Kind::Filament: return "filament_settings_id";
    case Kind::Process: return "print_settings_id";
    case Kind::Printer: break;
    }
    return "printer_settings_id";
}

std::optional<nlohmann::json> read_json(const fs::path& file)
{
    std::ifstream stream(file);
    if (!stream)
        return std::nullopt;
    nlohmann::json json = nlohmann::json::parse(stream, nullptr, false);
    if (json.is_discarded() || !json.is_object())
        return std::nullopt;
    return json;
}

// OrcaSlicer.conf: JSON, then possibly a "# MD5 checksum" line, which reading
// one value leaves unread.
std::optional<nlohmann::json> read_config(const fs::path& file)
{
    std::ifstream stream(file);
    nlohmann::json json;
    try {
        stream >> json;
    } catch (const nlohmann::json::parse_error&) {
        return std::nullopt;
    }
    return json.is_object() ? std::optional<nlohmann::json>(std::move(json)) : std::nullopt;
}

std::string string_value(const nlohmann::json& json, const char* key)
{
    const auto found = json.find(key);
    return found != json.end() && found->is_string() ? found->get<std::string>() : std::string();
}

bool has_json_files(const fs::path& folder)
{
    std::error_code error;
    if (!fs::is_directory(folder, error))
        return false;
    for (const fs::directory_entry& entry : fs::directory_iterator(folder, error))
        if (entry.path().extension() == ".json")
            return true;
    return false;
}

} // namespace

std::vector<OrcaImportItem> plan_orca_import(const std::vector<std::string>& files, const OrcaImportCatalog& catalog,
                                             const fs::path& staging)
{
    std::vector<OrcaImportItem> items;
    // Names this import takes, so two renamed copies never share one.
    std::set<std::pair<Kind, std::string>> taken;
    std::vector<nlohmann::json> contents;
    for (const std::string& file : files) {
        OrcaImportItem item;
        item.source = item.file = file;
        const fs::path path     = fs::u8path(file);
        item.kind               = kind_of_folder(path);
        item.name               = path.stem().u8string();
        std::optional<nlohmann::json> json = read_json(path);
        if (!json) {
            item.outcome = OrcaImportItem::Outcome::NotImported;
            item.reason  = OrcaImportItem::Reason::Unreadable;
        } else {
            if (const std::string name = string_value(*json, "name"); !name.empty())
                item.name = name;
            const bool is_preset = json->contains("printer_settings_id") || json->contains("print_settings_id") ||
                                   json->contains("filament_settings_id");
            if (string_value(*json, "version").empty())
                item.reason = OrcaImportItem::Reason::NoVersion;
            else if (!is_preset)
                item.reason = OrcaImportItem::Reason::NotAPreset;
            if (item.reason != OrcaImportItem::Reason::None)
                item.outcome = OrcaImportItem::Outcome::NotImported;
            taken.insert({item.kind, item.name});
        }
        items.push_back(std::move(item));
        contents.push_back(json ? std::move(*json) : nlohmann::json());
    }

    for (size_t index = 0; index < items.size(); ++index) {
        OrcaImportItem& item = items[index];
        if (item.outcome != OrcaImportItem::Outcome::Pending)
            continue;
        nlohmann::json& json = contents[index];
        item.base            = string_value(json, "inherits");
        const bool in_batch  = std::any_of(items.begin(), items.end(), [&](const OrcaImportItem& other) {
            return &other != &item && other.kind == item.kind && other.name == item.base;
        });
        if (!item.base.empty() && !in_batch && !catalog.has_base(item.kind, item.base)) {
            item.outcome = OrcaImportItem::Outcome::NotImported;
            item.reason  = OrcaImportItem::Reason::MissingBase;
            continue;
        }
        if (!catalog.has(item.kind, item.name))
            continue;

        std::string renamed = item.name + " (Orca copy)";
        for (int copy = 2; catalog.has(item.kind, renamed) || taken.count({item.kind, renamed}) != 0; ++copy)
            renamed = item.name + " (Orca copy " + std::to_string(copy) + ")";
        taken.insert({item.kind, renamed});
        json["name"]                    = renamed;
        json[settings_id_key(item.kind)] = renamed;
        // Numbered, not named: a preset name can hold characters a file name cannot.
        const fs::path copy = staging / (std::to_string(index) + ".json");
        std::ofstream  stream(copy);
        stream << json.dump(4);
        if (!stream)
            throw std::runtime_error("Could not write the renamed copy " + copy.u8string());
        item.file       = copy.u8string();
        item.renamed_to = renamed;
    }
    return items;
}

void settle_orca_import(std::vector<OrcaImportItem>& items, const std::vector<std::string>& imported)
{
    for (OrcaImportItem& item : items) {
        if (item.outcome != OrcaImportItem::Outcome::Pending)
            continue;
        if (std::find(imported.begin(), imported.end(), item.file) != imported.end()) {
            item.outcome = OrcaImportItem::Outcome::Imported;
        } else {
            item.outcome = OrcaImportItem::Outcome::NotImported;
            item.reason  = OrcaImportItem::Reason::NotLoaded;
        }
    }
}

OrcaPresetFiles scan_orca_presets(const fs::path& account_folder)
{
    OrcaPresetFiles presets;
    const auto scan = [&](const char* subfolder, std::vector<std::string>& names) {
        std::error_code error;
        const fs::path  folder = account_folder / subfolder;
        if (!fs::is_directory(folder, error))
            return;
        std::vector<fs::path> files;
        for (const fs::directory_entry& entry : fs::directory_iterator(folder, error))
            if (entry.is_regular_file(error) && entry.path().extension() == ".json")
                files.push_back(entry.path());
        std::sort(files.begin(), files.end());
        for (const fs::path& file : files) {
            names.push_back(file.stem().u8string());
            presets.files.push_back(file.u8string());
        }
    };
    // Base machine profiles first, then their material and process children.
    scan(kPrinterFolder, presets.printers);
    scan(kFilamentFolder, presets.filaments);
    scan(kProcessFolder, presets.processes);
    return presets;
}

std::optional<fs::path> orca_account_folder(const fs::path& orca_root)
{
    std::string configured;
    const fs::path config = orca_root / "OrcaSlicer.conf";
    std::error_code error;
    if (fs::is_regular_file(config, error)) {
        std::optional<nlohmann::json> json = read_config(config);
        if (!json)
            return std::nullopt;
        const auto app = json->find("app");
        if (app != json->end() && app->is_object())
            configured = string_value(*app, "preset_folder");
    }

    const fs::path user = orca_root / kUserFolder;
    if (!configured.empty())
        return user / configured;
    fs::path        newest = user / kDefaultFolder;
    fs::file_time_type written{};
    for (const fs::directory_entry& account : fs::directory_iterator(user, error)) {
        for (const fs::directory_entry& item : fs::directory_iterator(account.path() / kPrinterFolder, error)) {
            if (item.path().extension() != ".json")
                continue;
            if (const fs::file_time_type time = item.last_write_time(error); time > written) {
                written = time;
                newest  = account.path();
            }
        }
        error.clear();
    }
    return newest;
}

std::optional<fs::path> orca_account_folder_for_pick(const fs::path& picked)
{
    std::error_code error;
    if (fs::is_directory(picked / kUserFolder, error))
        return orca_account_folder(picked);
    if (has_json_files(picked / kPrinterFolder) || has_json_files(picked / kFilamentFolder) ||
        has_json_files(picked / kProcessFolder))
        return picked;
    if (picked.filename() == kPrinterFolder && has_json_files(picked))
        return picked.parent_path();
    // The user folder: its account folders hold the presets.
    if (picked.filename() == kUserFolder)
        return orca_account_folder(picked.parent_path());
    return std::nullopt;
}

} // namespace Slic3r::GUI::JusPrin::Home

