16	// OrcaSlicer's own names (Preset.hpp, PresetBundle.hpp), repeated here so
17	// this file needs no libslic3r.
18	const char* const kUserFolder    = "user";     // PRESET_USER_DIR
19	const char* const kDefaultFolder = "default";  // DEFAULT_USER_FOLDER_NAME
20	const char* const kPrinterFolder = "machine";  // PRESET_PRINTER_NAME
