24	using Kind = OrcaImportItem::Kind;
25	
26	Kind kind_of_folder(const fs::path& file)
27	{
28	    const std::string folder = file.parent_path().filename().u8string();
29	    return folder == kFilamentFolder ? Kind::Filament : folder == kProcessFolder ? Kind::Process : Kind::Printer;
30	}
31	
32	// The key import_json_presets tells the kinds apart by, which also holds
33	// the preset's name.
34	const char* settings_id_key(Kind kind)
35	{
36	    switch (kind) {
37	    case Kind::Filament: return "filament_settings_id";
38	    case Kind::Process: return "print_settings_id";
39	    case Kind::Printer: break;
40	    }
41	    return "printer_settings_id";
42	}
