44	std::optional<nlohmann::json> read_json(const fs::path& file)
45	{
46	    std::ifstream stream(file);
47	    if (!stream)
48	        return std::nullopt;
49	    nlohmann::json json = nlohmann::json::parse(stream, nullptr, false);
50	    if (json.is_discarded() || !json.is_object())
51	        return std::nullopt;
52	    return json;
53	}
54	
55	// OrcaSlicer.conf: JSON, then possibly a "# MD5 checksum" line, which reading
56	// one value leaves unread.
57	std::optional<nlohmann::json> read_config(const fs::path& file)
58	{
59	    std::ifstream stream(file);
60	    nlohmann::json json;
61	    try {
62	        stream >> json;
63	    } catch (const nlohmann::json::parse_error&) {
64	        return std::nullopt;
65	    }
66	    return json.is_object() ? std::optional<nlohmann::json>(std::move(json)) : std::nullopt;
67	}
