  if (!form) return 'no form';
  const emailRow = form.cloneNode(false);
  const email = form.querySelector('input').cloneNode();
  email.disabled = false;
  emailRow.appendChild(email);
  const pwRow = form.cloneNode(false);
  const pw = email.cloneNode();
  pw.type = 'password'; pw.placeholder = 'Password'; pw.setAttribute('aria-label', 'Password');
