    76	std::string cloud_server_from_gateway(const std::string& gateway)
    77	{
    78	    const std::size_t ent = gateway.find("/ent/");
    79	    if (ent != std::string::npos)
    80	        return gateway.substr(0, ent);
    81	    const std::size_t scheme = gateway.find("://");
    82	    const std::size_t path   = gateway.find('/', scheme == std::string::npos ? 0 : scheme + 3);
    83	    return path == std::string::npos ? gateway : gateway.substr(0, path);
    84	}
    85	
    86	CloudSignIn::CloudSignIn(std::string server, std::string gateway, std::string default_model, CloudAccountDeps deps,
    87	                         CloudAccountStore store, AgentFactory agents)
    88	    : m_server(std::move(server)), m_gateway(std::move(gateway)), m_default_model(std::move(default_model)),
    89	      m_deps(std::move(deps)), m_store(std::move(store)), m_agents(std::move(agents)), m_inbox(std::make_shared<Inbox>())
    90	{}
    91	
    92	CloudSignIn::~CloudSignIn() { cancel(); }
