   152	    m_who.reset();
   153	    m_models.reset();
   154	    ask_who(m_generation);
   155	    ask_models(m_generation);
   156	}
   157	
   158	void CloudSignIn::ask_who(std::uint64_t generation)
   159	{
   160	    std::weak_ptr<Inbox> inbox = m_inbox;
   161	    m_deps.get(m_server + "/jusprin/api/me/", m_token, [inbox, generation](CloudHttpResult result) {
   162	        if (const auto target = inbox.lock())
   163	            target->push({generation, Inbox::Kind::Who, {}, std::move(result)});
   164	    });
   165	}
   166	
   167	void CloudSignIn::ask_models(std::uint64_t generation)
   168	{
   169	    const std::size_t    slash = m_gateway.rfind('/');
   170	    const std::string    url   = (slash == std::string::npos ? m_gateway : m_gateway.substr(0, slash)) + "/models";
   171	    std::weak_ptr<Inbox> inbox = m_inbox;
   172	    m_deps.get(url, m_token, [inbox, generation](CloudHttpResult result) {
   173	        if (const auto target = inbox.lock())
   174	            target->push({generation, Inbox::Kind::Models, {}, std::move(result)});
   175	    });
   176	}
   177	
   178	std::optional<CloudEmailStep> CloudSignIn::email_step() const
   179	{
   180	    if (m_phase != CloudSignInPhase::Email)
   181	        return std::nullopt;
   182	    return m_email;
   183	}
   184	
   185	void CloudSignIn::ask_server(const std::string& endpoint, const json& body)
   186	{
   187	    m_asked             = endpoint;
   188	    m_email.busy        = true;
   189	    m_email.refusal.clear();
   190	    m_email.code_resent = false;
   191	    std::weak_ptr<Inbox> inbox = m_inbox;
   192	    const std::uint64_t generation = m_generation;
   193	    m_deps.post(m_server + "/ent/jusprin/v2/auth/" + endpoint, body.dump(), [inbox, generation](CloudHttpResult result) {
   194	        if (const auto target = inbox.lock())
   195	            target->push({generation, Inbox::Kind::Auth, {}, std::move(result)});
   196	    });
   197	}
   198	
   199	bool CloudSignIn::start_email(const std::string& email)
   200	{
   201	    if (m_phase != CloudSignInPhase::Idle || email.empty())
   202	        return false;
   203	    ++m_generation;
   204	    m_phase       = CloudSignInPhase::Email;
   205	    m_email       = CloudEmailStep{};
   206	    m_email.email = email;
   207	    ask_server("email", {{"email", email}});
   208	    return true;
   209	}
   210	
   211	bool CloudSignIn::submit_code(const std::string& code)
   212	{
   213	    if (m_phase != CloudSignInPhase::Email || m_email.busy || m_email.step != CloudEmailStep::Step::Code)
   214	        return false;
   215	    ask_server("code", {{"email", m_email.email}, {"code", code}});
   216	    return true;
   217	}
   218	
   219	bool CloudSignIn::submit_password(const std::string& password)
   220	{
   221	    if (m_phase != CloudSignInPhase::Email || m_email.busy || m_email.step != CloudEmailStep::Step::Password)
   222	        return false;
   223	    ask_server("password", {{"email", m_email.email}, {"password", password}});
   224	    return true;
   225	}
   226	
   227	bool CloudSignIn::send_code()
   228	{
   229	    if (m_phase != CloudSignInPhase::Email || m_email.busy || m_email.step == CloudEmailStep::Step::Asking)
   230	        return false;
   231	    ask_server("resend", {{"email", m_email.email}});
   232	    return true;
   233	}
   234	
   235	// What an auth endpoint answered. A token goes on to the same check as the
   236	// browser's; a refusal the person can act on stays on the step; anything
   237	// else ends the sign-in with one generic error.
   238	std::optional<CloudSignInOutcome> CloudSignIn::answered(CloudHttpResult http)
   239	{
   240	    m_email.busy = false;
   241	    const json  body    = json::parse(http.body, nullptr, false);
   242	    const std::string refusal = body.is_object() ? body.value("/error/code"_json_pointer, std::string()) : std::string();
   243	    const auto  refused = [&](std::initializer_list<const char*> codes) {
   244	        return std::any_of(codes.begin(), codes.end(), [&](const char* code) { return refusal == code; });
   245	    };
   246	
   247	    if (m_asked == "email" && http.status == 200 && body.is_object()) {
   248	        const std::string method = body.value("method", "");
   249	        if (method == "code" || method == "password") {
   250	            m_email.step = method == "code" ? CloudEmailStep::Step::Code : CloudEmailStep::Step::Password;
   251	            return std::nullopt;
   252	        }
   253	    }
   254	    if (m_asked == "email" && refused({"too_many_codes"}))
   255	        return failed("too_many_codes", "Too many codes were sent to this address. Try again in an hour.", true);
   256	    if (m_asked == "resend" && http.status == 204) {
   257	        m_email.step        = CloudEmailStep::Step::Code;
   258	        m_email.refusal.clear();
   259	        m_email.code_resent = true;
   260	        return std::nullopt;
   261	    }
   262	    if ((m_asked == "code" || m_asked == "password") && http.status == 200 && body.is_object()) {
   263	        const std::string token = body.value("access_token", "");
   264	        if (!token.empty()) {
   265	            begin_check(token);
   266	            return std::nullopt;
   267	        }
   268	    }
   269	    if ((m_asked == "code" && refused({"wrong_code", "expired_code", "too_many_tries"})) ||
   270	        (m_asked == "password" && refused({"wrong_password", "too_many_tries"})) ||
   271	        (m_asked == "resend" && refused({"too_many_codes"}))) {
   272	        m_email.refusal    = refusal;
   273	        m_email.tries_left = body.value("tries_left", 0);
   274	        return std::nullopt;
   275	    }
   276	    return failed("sign_in_failed", "JusPrin couldn't sign you in. Try again.", true);
   277	}
   278	
   279	void CloudSignIn::cancel()
   280	{
   281	    if (m_phase == CloudSignInPhase::Browser && m_deps.cancel_authorize)
   282	        m_deps.cancel_authorize();
   283	    ++m_generation;
   284	    m_phase = CloudSignInPhase::Idle;
   285	    m_token.clear();
   286	    m_who.reset();
   287	    m_models.reset();
   288	}
   289	
   290	std::optional<CloudSignInOutcome> CloudSignIn::poll()
   291	{
   292	    if (m_deps.pump)
   293	        m_deps.pump();
   294	    while (std::optional<Inbox::Item> item = m_inbox->pop()) {
   295	        if (item->generation != m_generation)
   296	            continue; // from a sign-in that was cancelled
   297	        switch (item->kind) {
   298	        case Inbox::Kind::Authorized:
   299	            if (m_phase != CloudSignInPhase::Browser)
   300	                continue;
   301	            if (!item->authorization.ok || item->authorization.access_token.empty())
   302	                return failed("sign_in_failed", "Signing in didn't finish. Nothing was saved. Try again.", true);
   303	            begin_check(std::move(item->authorization.access_token));
   304	            break;
   305	        case Inbox::Kind::Auth:
   306	            if (m_phase != CloudSignInPhase::Email)
   307	                continue;
   308	            if (std::optional<CloudSignInOutcome> outcome = answered(std::move(item->http)))
   309	                return outcome;
   310	            break;
   311	        case Inbox::Kind::Who: m_who = std::move(item->http); break;
   312	        case Inbox::Kind::Models: m_models = std::move(item->http); break;
   313	        }
   314	        if (m_phase == CloudSignInPhase::Checking && m_who && m_models)
   315	            return finish_check();
   316	    }
   317	    return std::nullopt;
   318	}
   319	
   320	std::optional<CloudSignInOutcome> CloudSignIn::finish_check()
   321	{
   322	    const CloudHttpResult who    = std::move(*m_who);
   323	    const CloudHttpResult models = std::move(*m_models);
   324	    m_who.reset();
   325	    m_models.reset();
   326	    if (refused(who) || refused(models)) {
   327	        m_phase = CloudSignInPhase::Idle;
   328	        m_token.clear();
   329	        CloudSignInOutcome outcome;
   330	        outcome.kind = CloudSignInOutcome::Kind::Expired;
   331	        return outcome;
   332	    }
   333	    const json who_json    = json::parse(who.body, nullptr, false);
   334	    const json models_json = json::parse(models.body, nullptr, false);
   335	    if (who.status != 200 || models.status != 200 || !who_json.is_object() || !models_json.is_object() ||
   336	        !models_json.contains("data"))
   337	        return failed("account_unreachable", "JusPrin couldn't be reached to finish signing in. Try again.", true);
   338	
   339	    CloudAccountRecord record;
   340	    record.token = m_token;
   341	    // /jusprin/api/me/ answers {"user": {"email", ...}, "ai_credits": {...}}.
   342	    record.email = who_json.value("/user/email"_json_pointer, std::string());
   343	    for (const json& entry : models_json["data"]) {
   344	        const std::string id = entry.value("id", ""), format = entry.value("format", "");
   345	        if (!id.empty() && !format.empty())
   346	            record.formats.emplace_back(id, format);
   347	    }
   348	    // The agent is for the provider's default model, or else the first the
   349	    // server lists.
   350	    auto chosen = std::find_if(record.formats.begin(), record.formats.end(),
   351	                               [this](const auto& entry) { return entry.first == m_default_model; });
   352	    if (chosen == record.formats.end())
   353	        chosen = record.formats.begin();
   354	    AgentServicePtr service = chosen == record.formats.end() ? nullptr : m_agents(m_token, chosen->first, chosen->second);
   355	    if (!service)
   356	        return failed("account_no_models", "JusPrin has no Agent model for this account right now. Try again later.", true);
   357	
   358	    CloudSignInOutcome outcome;
   359	    outcome.kind    = CloudSignInOutcome::Kind::SignedIn;
   360	    outcome.email   = record.email;
   361	    outcome.saved   = m_store.save && m_store.save(record);
   362	    outcome.service = std::move(service);
   363	    m_phase         = CloudSignInPhase::Idle;
   364	    m_token.clear();
   365	    return outcome;
   366	}
   367	
   368	CloudSignInOutcome CloudSignIn::failed(const std::string& code, const std::string& message, bool retryable)
   369	{
   370	    m_phase = CloudSignInPhase::Idle;
   371	    m_token.clear();
   372	    CloudSignInOutcome outcome;
   373	    outcome.kind  = CloudSignInOutcome::Kind::Failed;
   374	    outcome.error = AgentError{code, message, retryable};
   375	    return outcome;
   376	}
   377	
   378	std::optional<CloudAccountRecord> CloudSignIn::account() const
   379	{
   380	    if (!m_store.load)
   381	        return std::nullopt;
   382	    std::optional<CloudAccountRecord> record = m_store.load();
   383	    if (!record || record->token.empty())
   384	        return std::nullopt;
   385	    return record;
   386	}
   387	
   388	bool CloudSignIn::sign_out()
   389	{
   390	    const std::optional<CloudAccountRecord> record = account();
   391	    if (!record || !m_store.erase || !m_store.erase())
   392	        return false;
   393	    cancel();
   394	    if (m_deps.revoke)
   395	        m_deps.revoke(m_server + "/o/revoke_token/", kCloudClientId, record->token);
   396	    return true;
   397	}
   398	
   399	} // namespace Slic3r::GUI::JusPrin::Agent

