    17	std::string percent_encoded(const std::string& text)
    18	{
    19	    std::string encoded;
    20	    for (const unsigned char c : text) {
    21	        if (std::isalnum(c) || c == '-' || c == '_' || c == '.' || c == '~') {
    22	            encoded += static_cast<char>(c);
    23	        } else {
    24	            char escaped[4];
    25	            std::snprintf(escaped, sizeof(escaped), "%%%02X", c);
    26	            encoded += escaped;
    27	        }
    28	    }
    29	    return encoded;
    30	}
    31	
    32	std::string query(const std::vector<std::pair<std::string, std::string>>& parameters)
    33	{
    34	    std::string text;
    35	    for (const auto& [name, value] : parameters)
    36	        text += (text.empty() ? "" : "&") + name + "=" + percent_encoded(value);
    37	    return text;
    38	}
    39	
    40	bool refused(const CloudHttpResult& result) { return result.status == 401 || result.status == 403; }
    41	
    42	} // namespace
    43	
    44	// What the injected browser and HTTP calls report, queued until poll(). Shared
    45	// with the callbacks so one that arrives after this object is gone has
    46	// somewhere harmless to go.
    47	struct CloudSignIn::Inbox
    48	{
    49	    enum class Kind { Authorized, Who, Models, Auth };
    50	    struct Item
    51	    {
    52	        std::uint64_t            generation{0};
    53	        Kind                     kind{Kind::Authorized};
    54	        CloudAuthorizationResult authorization;
    55	        CloudHttpResult          http;
    56	    };
    57	    std::mutex       mutex;
    58	    std::deque<Item> items;
    59	
    60	    void push(Item item)
    61	    {
    62	        std::lock_guard<std::mutex> lock(mutex);
    63	        items.push_back(std::move(item));
    64	    }
    65	    std::optional<Item> pop()
    66	    {
    67	        std::lock_guard<std::mutex> lock(mutex);
    68	        if (items.empty())
    69	            return std::nullopt;
