        m_email.code_resent = m_email.step == CloudEmailStep::Step::Code;
        m_email.step        = CloudEmailStep::Step::Code;
        m_session           = session;
        return std::nullopt;
    }
    if (http.status == 200 && !token.empty()) {
        m_session.clear();
        begin_check(token);
        return std::nullopt;
