    else if (http.status == 400 && m_asked == "login")
        m_email.refusal = errors("too_many_login_attempts") ? "too_many_tries" : "wrong_password";
    else
        return failed("sign_in_failed", "JusPrin couldn't sign you in. Try again.", true);
    return std::nullopt;
