content.content:
def icon(kind, color='--text-secondary', size=16):
    return (f'<span data-c="Icon:Type={kind}" data-icon="{kind}" aria-hidden="true" style="{BOX}width:{size}px;height:{size}px;color:var({color});display:inline-block">'
            f'<svg viewBox="0 0 24 24" width="100%" height="100%" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="display:block">{ICONS[kind]}</svg></span>')

def text(cls, s, color='--text-primary', extra='align-self:stretch', nowrap=False):
    nw = 'white-space:nowrap;' if nowrap else ''
    return f'<div class="{cls}" style="{BOX}{extra};{nw}color:var({color})">{escape(s)}</div>'

def rich(cls, html, color='--text-primary', extra='align-self:stretch'):
    return f'<div class="{cls}" style="{BOX}{extra};color:var({color})">{html}</div>'

def col(children, gap=8, extra='align-self:stretch', pad='', name=None, align='flex-start'):
    n = f' data-n="{escape(name)}"' if name else ''
    return f'<div{n} style="{BOX}{extra};display:flex;flex-direction:column;gap:var(--space-{gap});align-items:{align};{pad}">' + ''.join(children) + '</div>'

def row(children, gap=8, extra='align-self:stretch', justify='flex-start', align='center', name=None):
    n = f' data-n="{escape(name)}"' if name else ''
    return f'<div{n} style="{BOX}{extra};display:flex;gap:var(--space-{gap});justify-content:{justify};align-items:{align}">' + ''.join(children) + '</div>'

BTN = 'appearance:none;border:0;margin:0;font:inherit;cursor:pointer;'

def primary(label, small=False, block=False):
    """Button/Primary (34 high) or its small recipe (28), bundle .jp-btn-primary."""
    size = 'height:28px;padding:var(--space-4) var(--space-16);' if small else 'height:34px;padding:var(--space-8) var(--space-16);'
    w = 'align-self:stretch;' if block else ''
    return (f'<button type="button" data-c="Button/Primary:State=Default" style="{BTN}{BOX}{w}{size}display:flex;justify-content:center;align-items:center;background:var(--action-primary);border-radius:var(--radius-medium)">'
            f'<span class="body-small-bold" style="white-space:nowrap;color:var(--action-on-primary)">{escape(label)}</span></button>')

def secondary(label, block=False, trailing=None):
    """Button/Secondary, 32 high, bundle .jp-btn-secondary."""
    w = 'align-self:stretch;' if block else ''
    t = icon(trailing, '--text-primary', 14) if trailing else ''
    return (f'<button type="button" data-c="Button/Secondary:State=Default" style="{BTN}{BOX}{w}min-height:var(--component-buttonSecondary-height);display:flex;gap:6px;padding:6px var(--space-12);justify-content:center;align-items:center;background:transparent;border-radius:var(--radius-small);box-shadow:inset 0 0 0 1px var(--border-subtle)">'
            f'<span class="body-small" style="white-space:nowrap;color:var(--text-primary)">{escape(label)}</span>{t}</button>')

def link(label):
    """Button/Link, 26 high, Label Bold, bundle .jp-link."""
    return (f'<button type="button" data-c="Button/Link:State=Normal" style="{BTN}{BOX}height:26px;display:flex;align-items:center;padding:0 var(--space-4);background:transparent;border-radius:var(--radius-small)">'
            f'<span class="label-bold" style="white-space:nowrap;color:var(--action-primary)">{escape(label)}</span></button>')

def dismiss():
    return (f'<button type="button" aria-label="Dismiss" data-c="Button/IconCompact" style="{BTN}{BOX}width:26px;height:26px;display:flex;justify-content:center;align-items:center;background:transparent;border-radius:var(--radius-small)">'
            + icon('x', '--text-secondary', 16) + '</button>')

# ---- the chip and Prepare (as build_file_printer_page.py) -----------------------------------------------------------
BOARDS = [
    ('first-run-welcome-01-clip-beat-1', 'First run · 01 · Welcome, the clip at beat 1', welcome(1), -1440, TOP),
    ('first-run-welcome-02-clip-final-frame', 'First run · 02 · Welcome, the clip’s final frame', welcome(4), -80, TOP),
    ('first-run-welcome-03-clip-storyboard', 'First run · 03 · The clip’s four beats', storyboard(), 1280, TOP),
]
# The rest of the sequence, a row per step under the welcome, and the flow board beside the welcome row.
ROW_Y = [TOP + 940, TOP + 1880, TOP + 2820]
BOARDS += [
    ('first-run-04-welcome-sign-in-waiting', 'First run · 04 · Welcome, waiting on the browser sign-in', welcome(1, 'waiting'), -1440, ROW_Y[0]),
    ('first-run-05-welcome-signed-in', 'First run · 05 · Welcome, signed in, just before step 2', welcome(1, 'signed-in'), -80, ROW_Y[0]),
    ('first-run-06-preferences-over-welcome', 'First run · 06 · Preferences › Agent over the welcome, adding a key', over_welcome(), 1280, ROW_Y[0]),
    ('first-run-07-orcaslicer-import', 'First run · 07 · Printers: bring them from OrcaSlicer', orca_import(), -1440, ROW_Y[1]),
    ('first-run-08-add-printer', 'First run · 08 · Printers: the add-printer form, with Skip', add_printer_step(), -80, ROW_Y[1]),
    ('first-run-09-home-after-sign-in', 'First run · 09 · Home after sign-in and an OrcaSlicer import',
     home(connected_card(), [printer_card('Bambu Lab P1S', 'PLA', '#1F1F1F'), printer_card('Prusa MK4', 'PETG', '#9AA0A6')],
          'STL, 3MF, STEP, OBJ, AMF, SVG or ZIP. JusPrin asks what the part is for, then plans the print for your Bambu Lab P1S.'), -1440, ROW_Y[2]),
    ('first-run-10-home-after-just-slice', 'First run · 10 · Home after Just slice, with the assumed default',
     home(collapsed_doors(), [printer_card('Bambu Lab A1 mini', 'PLA', '#1F1F1F', assumed=True)],
          'STL, 3MF, STEP, OBJ, AMF, SVG or ZIP. JusPrin slices it for your Bambu Lab A1 mini.'), -80, ROW_Y[2]),
    ('first-run-11-flow', 'First run · 11 · The flow: Welcome → Printers → Home', flow(), 2640, TOP, FLOW_W, FLOW_H),
]

def wrap(title, inner, w=SCREEN_W, h=SCREEN_H):
    return f'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>{escape(title)}</title>
<script src="./support.js"></script>
<link rel="stylesheet" href="ds/jusprin/tokens.css">
</head>
<body>
<x-dc>
<helmet>
<style>
body{{margin:0}}
</style>
</helmet>
<div data-theme="{{{{theme}}}}" class="body" style="width:{w}px;height:{h}px;position:relative;overflow:hidden;background:var(--surface-canvas);color:var(--text-primary);font-family:var(--font-sans)">{inner}</div>
</x-dc>
<script type="text/x-dc" data-dc-script data-props='{{"theme":{{"editor":"enum","options":["light","dark"],"default":"light"}},"$preview":{{"width":{w},"height":{h}}}}}'>
class Component extends DCLogic {{
  renderVals() {{ const theme = this.props.theme ?? 'light'; return {{ theme, lockup: {json.dumps(LOCKUP)}[theme] }}; }}
}}
</script>
</body>
</html>
'''

canvas_path = proj / 'canvas.json'
canvas = json.loads(canvas_path.read_text())
# Variants A and B are withdrawn (Kenneth, 2026-11-02); their boards and notes go, and nothing else on the page moved for them.
removed = [k for k in canvas['boards'] if k.startswith(('first-run-a-', 'first-run-b-'))]
for k in removed:
    del canvas['boards'][k]
    canvas['order'].remove(k)
    (proj / k).unlink(missing_ok=True)
for nid in ('first-run-title', 'first-run-replaces', 'first-run-b-title', 'first-run-b-about'):
    canvas['notes'].pop(nid, None)
    if nid in canvas['noteOrder']:
        canvas['noteOrder'].remove(nid)
names = []
for stem, title, inner, x, y, *size in BOARDS:
    w, h = size or (SCREEN_W, SCREEN_H)
    name = stem + '.dc.html'
    (proj / name).write_text(wrap(title.replace('First run · ', ''), inner, w, h))
    names.append(name)
    canvas['boards'][name] = {'x': x, 'y': y, 'w': w, 'h': h, 'title': title, 'page': PAGE}
    if name not in canvas['order']:
        canvas['order'].append(name)
canvas['notes']['first-run-welcome-title'] = {'x': -1440, 'y': TOP - 100, 'text': 'First launch: one welcome screen', 'kind': 'title1', 'size': 40, 'maxW': 2400, 'page': PAGE}
canvas['notes']['first-run-welcome-about'] = {'x': -1920, 'y': TOP, 'w': 420, 'page': PAGE, 'fill': 'purple',
    'text': 'Decided by Kenneth, 2026-11-02. No wizard: the first launch is one welcome screen, a looping silent clip on the left and the words and doors on the right. '
            'It replaces the onboarding wizard (onboarding-00 to 20, now at the bottom of this page) and Welcome 1b.\n\n'
            'The proposition is expert help with a failed print, now, from an AI that can see the file, the settings and the slice and fixes the settings. '
            'One door is primary, the first-month offer; the two free doors show their cost; “Just slice for now” is a link.\n\n'
            'After the welcome, onboarding is a sequence, Welcome → Printers → Home, and every door comes back into it (11 is the flow; 04 to 10 the screens).\n\n'
            'The clip’s pictures and strings follow the reference animatic in design-captures/value-prop-2026-11; 03 says which parts are placeholders.'}
canvas['notes']['first-run-flow-title'] = {'x': -1440, 'y': ROW_Y[0] - 100, 'text': 'First launch, after the doors: the detours, Printers and Home', 'kind': 'title1', 'size': 40, 'maxW': 2400, 'page': PAGE}
canvas['notes']['first-run-flow-about'] = {'x': -1920, 'y': ROW_Y[0], 'w': 420, 'page': PAGE, 'fill': 'purple',
    'text': 'Decided by Kenneth, 2026-11-02 (“Draw them”). A controller owns the step; the doors are detours that return into the sequence.\n\n'
            'Row 1, step 1: the sign-in door waiting on the browser (04) and signed in (05); Preferences › Agent modal over the welcome for the key door (06).\n\n'
            'Row 2, step 2: OrcaSlicer found (07), or the add-printer form with Skip, use a default (08). JusPrin v1 found skips the step for the welcome-back window, onboarding-v1-01 to 03.\n\n'
            'Row 3, step 3: Home after sign-in with an OrcaSlicer import (09), and after Just slice with the assumed default (10).\n\n'
            'Home has no agent column today; 09 and 10 put an Agent group above Printers in its right column. The printers, filament counts and the default printer are examples.'}

# The old wizard contradicts the sequence. Its boards stay, moved to the bottom of the page under a note; nothing else moves.
WIZARD_Y = ROW_Y[2] + 1260
wizard = sorted(k for k, v in canvas['boards'].items() if v.get('page') == PAGE and re.match(r'onboarding-\d', k))
if all(canvas['boards'][k]['y'] < TOP for k in wizard):
    for k in wizard:
        canvas['boards'][k]['y'] += WIZARD_Y
canvas['notes']['onboarding-wizard-superseded-title'] = {'x': -1440, 'y': WIZARD_Y - 100, 'text': 'Superseded: the onboarding wizard', 'kind': 'title1', 'size': 40, 'maxW': 2400, 'page': PAGE}
canvas['notes']['onboarding-wizard-superseded'] = {'x': -1920, 'y': WIZARD_Y, 'w': 420, 'page': PAGE, 'fill': 'purple',
