def icon(kind, color='--text-secondary', size=16):
    return (f'<span data-c="Icon:Type={kind}" data-icon="{kind}" aria-hidden="true" style="{BOX}width:{size}px;height:{size}px;color:var({color});display:inline-block">'
            f'<svg viewBox="0 0 24 24" width="100%" height="100%" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="display:block">{ICONS[kind]}</svg></span>')

def text(cls, s, color='--text-primary', extra='align-self:stretch', nowrap=False):
    nw = 'white-space:nowrap;' if nowrap else ''
    return f'<div class="{cls}" style="{BOX}{extra};{nw}color:var({color})">{escape(s)}</div>'

def rich(cls, html, color='--text-primary', extra='align-self:stretch'):
    return f'<div class="{cls}" style="{BOX}{extra};color:var({color})">{html}</div>'

def col(children, gap=8, extra='align-self:stretch', pad='', name=None, align='flex-start'):
    n = f' data-n="{escape(name)}"' if name else ''
    return f'<div{n} style="{BOX}{extra};display:flex;flex-direction:column;gap:var(--space-{gap});align-items:{align};{pad}">' + ''.join(children) + '</div>'

def row(children, gap=8, extra='align-self:stretch', justify='flex-start', align='center', name=None):
    n = f' data-n="{escape(name)}"' if name else ''
    return f'<div{n} style="{BOX}{extra};display:flex;gap:var(--space-{gap});justify-content:{justify};align-items:{align}">' + ''.join(children) + '</div>'

BTN = 'appearance:none;border:0;margin:0;font:inherit;cursor:pointer;'

def primary(label, small=False, block=False):
    """Button/Primary (34 high) or its small recipe (28), bundle .jp-btn-primary."""
    size = 'height:28px;padding:var(--space-4) var(--space-16);' if small else 'height:34px;padding:var(--space-8) var(--space-16);'
    w = 'align-self:stretch;' if block else ''
    return (f'<button type="button" data-c="Button/Primary:State=Default" style="{BTN}{BOX}{w}{size}display:flex;justify-content:center;align-items:center;background:var(--action-primary);border-radius:var(--radius-medium)">'
            f'<span class="body-small-bold" style="white-space:nowrap;color:var(--action-on-primary)">{escape(label)}</span></button>')

def secondary(label, block=False, trailing=None):
    """Button/Secondary, 32 high, bundle .jp-btn-secondary."""
    w = 'align-self:stretch;' if block else ''
    t = icon(trailing, '--text-primary', 14) if trailing else ''
    return (f'<button type="button" data-c="Button/Secondary:State=Default" style="{BTN}{BOX}{w}min-height:var(--component-buttonSecondary-height);display:flex;gap:6px;padding:6px var(--space-12);justify-content:center;align-items:center;background:transparent;border-radius:var(--radius-small);box-shadow:inset 0 0 0 1px var(--border-subtle)">'
            f'<span class="body-small" style="white-space:nowrap;color:var(--text-primary)">{escape(label)}</span>{t}</button>')

def link(label):
    """Button/Link, 26 high, Label Bold, bundle .jp-link."""
    return (f'<button type="button" data-c="Button/Link:State=Normal" style="{BTN}{BOX}height:26px;display:flex;align-items:center;padding:0 var(--space-4);background:transparent;border-radius:var(--radius-small)">'
            f'<span class="label-bold" style="white-space:nowrap;color:var(--action-primary)">{escape(label)}</span></button>')

def dismiss():
    return (f'<button type="button" aria-label="Dismiss" data-c="Button/IconCompact" style="{BTN}{BOX}width:26px;height:26px;display:flex;justify-content:center;align-items:center;background:transparent;border-radius:var(--radius-small)">'
            + icon('x', '--text-secondary', 16) + '</button>')

