# Variants A and B are withdrawn (Kenneth, 2026-11-02); their boards and notes go, and nothing else on the page moved for them.
removed = [k for k in canvas['boards'] if k.startswith(('first-run-a-', 'first-run-b-'))]
for k in removed:
