content.content:
76	function CodeStep({ email, onAction, onChangeEmail, onBrowser }: {
77	  email: EmailSignIn; onAction: Action; onChangeEmail: () => void; onBrowser: () => void;
78	}) {
79	  const [code, setCode] = useState('');
80	  const field = useRef<HTMLInputElement>(null);
81	  const refusal = refusalText(email);
82	  // A code that can no longer work: the way on is a new one.
83	  const spent = email.refusal === 'expired_code';
84	  const sendCode = () => onAction('onboarding_sign_in_send_code');
85	  // A new code empties the cells; so does typing after a wrong one.
86	  useEffect(() => {
87	    if (email.codeResent) setCode('');
88	  }, [email.codeResent]);
89	  useEffect(() => {
90	    if (email.refusal === 'wrong_code' && !email.busy) setCode('');
91	  }, [email.refusal, email.busy]);
92	  useEffect(() => {
93	    if (!email.busy) field.current?.focus();
94	  }, [email.busy]);
95	  return (
96	    <>
97	      <p className="onboarding-door-title">Check your email.</p>
98	      <p className="onboarding-door-detail">
99	        {email.codeResent ? 'We sent a new code to ' : 'We sent a 6-digit code to '}
100	        {email.email}.
101	      </p>
102	      <CodeField
103	        ref={field}
104	        value={code}
105	        refused={email.refusal === 'wrong_code' || spent}
106	        disabled={email.busy}
107	        onChange={setCode}
108	        onComplete={(digits) => onAction('onboarding_sign_in_code', { code: digits })}
109	      />
110	      {refusal ? (
111	        <p className="onboarding-error" role="alert">{refusal}</p>
112	      ) : (
113	        <p className="onboarding-door-note">The sixth digit signs you in. Read the email on any device.</p>
114	      )}
115	      {spent ? (
116	        <div className="onboarding-link-row">
117	          <button type="button" className="button-primary" disabled={email.busy} onClick={sendCode}>Send a new code</button>
118	          <LinkRow links={[['Change email', onChangeEmail], ['Use the browser instead', onBrowser]]} />
119	        </div>
120	      ) : (
121	        <LinkRow
122	          links={[['Send a new code', sendCode], ['Change email', onChangeEmail], ['Use the browser instead', onBrowser]]}
123	          cancel={() => onAction('onboarding_sign_in_cancel')}
124	        />
125	      )}
126	    </>
127	  );
128	}
129	
130	// The email door's choice, before anything is sent: an emailed code, which
131	// also makes the account of an address that has none, or the password.
132	function ChooseStep({ email, onAction, onChangeEmail }: { email: EmailSignIn; onAction: Action; onChangeEmail: () => void }) {
133	  const [password, setPassword] = useState('');
134	  const refusal = refusalText(email);
135	  const codeRefused = email.refusal === 'too_many_codes';
136	  return (
137	    <>
138	      <p className="onboarding-door-title">How do you want to sign in?</p>
139	      <p className="onboarding-door-detail">
140	        {email.email}.{' '}
141	        <button type="button" className="onboarding-link inline" onClick={onChangeEmail}>Change email</button>
142	      </p>
143	      <button type="button" className="button-primary onboarding-code-button" disabled={email.busy}
144	        onClick={() => onAction('onboarding_sign_in_send_code')}>
145	        Email me a 6-digit code
146	      </button>
147	      {codeRefused ? (
148	        <p className="onboarding-error" role="alert">{refusal}</p>
149	      ) : (
150	        <p className="onboarding-door-note">New here? The code makes your account.</p>
151	      )}
152	      <p className="onboarding-or"><span>or</span></p>
153	      <form className="onboarding-email-row" onSubmit={(event) => {
154	        event.preventDefault();
155	        if (password) onAction('onboarding_sign_in_password', { password });
156	      }}>
157	        <input className="onboarding-field" type="password" placeholder="Password" autoComplete="current-password"
158	          aria-label="Password" value={password} disabled={email.busy} onChange={(event) => setPassword(event.target.value)} />
159	        <button type="submit" className="button-secondary" disabled={email.busy || !password}>Sign in</button>
160	      </form>
