.onboarding-error {
  font: var(--font-label);
  color: var(--status-danger);
}

/* The design system's Button/Link: text only, Label Bold, action/primary. */
.onboarding-link {
  align-self: flex-start;
  padding: 4px 0;
  font: var(--font-label-bold);
  color: var(--action-primary);
  text-align: left;
  background: none;
  border: 0;
  cursor: pointer;
}

.onboarding-link:hover:not(:disabled) {
  color: var(--action-primary-hover);
  text-decoration: underline;
}

.onboarding-link:disabled {
  color: var(--action-disabled-text);
  cursor: default;
}
.onboarding-offer {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
  padding: 16px;
  background: var(--surface-selected);
  border-radius: var(--radius-medium);
  box-shadow: inset 0 0 0 1px var(--border-subtle);
}

.onboarding-door-title {
  display: flex;
  align-items: center;
  gap: 8px;
  font: var(--font-section);
}

.onboarding-door-detail {
  font: var(--font-body-small);
  color: var(--text-secondary);
}

.onboarding-door-button {
  margin-top: 8px;
}

/* The sign-in door (boards 13a, 12b, 12c, 13b, 12d): Google in the
   browser, or an address that stays in the app, then its code or password. */
.onboarding-door-note {
  font: var(--font-body-small);
  color: var(--text-secondary);
}

.onboarding-google {
  align-self: stretch;
  justify-content: center;
  min-height: var(--button-primary-height);
  margin-top: 8px;
  font: var(--font-body-small-bold);
  background: var(--surface-raised);
}

.onboarding-google img {
  width: var(--glyph-size);
  height: var(--glyph-size);
}

/* "or" between two rules. */
.onboarding-or {
  display: flex;
  align-self: stretch;
  align-items: center;
  gap: 12px;
  font: var(--font-body-small);
  color: var(--text-secondary);
}

.onboarding-or::before,
.onboarding-or::after {
  content: '';
  flex: 1 1 auto;
  border-top: 1px solid var(--border-subtle);
}

.onboarding-email-row {
  display: flex;
  align-self: stretch;
  gap: 12px;
  margin: 0;
}

.onboarding-field {
  flex: 1 1 auto;
  min-width: 0;
  height: var(--button-primary-height);
  padding: 0 var(--field-padding-x);
  font: var(--font-body);
  color: var(--text-primary);
  background: var(--surface-raised);
  border: 1px solid var(--border-subtle);
  border-radius: var(--field-radius);
}

.onboarding-field:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
}

.onboarding-email-row .button-primary,
.onboarding-email-row .button-secondary {
  flex: 0 0 auto;
  justify-content: center;
}

/* The email door's choice: the code button spans the card. */
.onboarding-code-button {
  align-self: stretch;
  justify-content: center;
  margin-top: 8px;
}

/* A link inside a sentence: the sentence's own type, in the link colour. */
.onboarding-link.inline {
  display: inline;
  padding: 0;
  font: inherit;
}

.onboarding-link-row {
  display: flex;
  align-self: stretch;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.onboarding-links {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
}

.onboarding-link-dot {
  padding: 0 4px;
  color: var(--text-secondary);
}

/* The design system's Field/Verification Code: six cells, one input. */
.code-field {
  position: relative;
}

.onboarding-door:disabled .onboarding-door-cost {
  color: var(--action-disabled-text);
}

.onboarding-spinner {
  flex: 0 0 auto;
  width: var(--glyph-size-large);
  height: var(--glyph-size-large);
  background: currentColor;
  -webkit-mask: url('@resources/jusprin/ui/icons/refresh-cw.svg') center / contain no-repeat;
  mask: url('@resources/jusprin/ui/icons/refresh-cw.svg') center / contain no-repeat;
  animation: onboarding-spin var(--onboarding-spin-duration) linear infinite;
}

@keyframes onboarding-spin {
  to {
    transform: rotate(360deg);
  }
}

