                f'border-radius:var(--radius-small);box-shadow:{ring};color:var(--text-primary)">{escape(digits[i] if i < len(digits) else "")}</div>')
    return f'<div data-n="Code" style="{BOX}display:flex;gap:var(--space-8);margin:var(--space-8) 0 var(--space-4)">' + ''.join(cell(i) for i in range(6)) + '</div>'

def google_button():
    return (f'<button type="button" data-c="Button/Secondary:State=Default" style="{BTN}{BOX}align-self:stretch;margin-top:var(--space-8);min-height:var(--component-buttonPrimary-height);display:flex;gap:6px;padding:6px var(--space-12);'
            'justify-content:center;align-items:center;background:var(--surface-raised);border-radius:var(--radius-small);box-shadow:inset 0 0 0 1px var(--border-subtle)">'
            f'<img src="{GOOGLE_MARK}" alt="" style="{BOX}width:16px;height:16px;display:block"><span class="body-small-bold" style="white-space:nowrap;color:var(--text-primary)">Continue with Google</span></button>')

def sign_in_door(state=None, title=True):
    """state: None (at rest), 'waiting' (on the browser), 'signed-in', 'choose', 'choose-wrong-password', 'code', 'code-wrong', 'code-spent'."""
    head = lambda s: text('section', s)
    if state is None:
        tail = [google_button(), or_rule(), row([field('you@example.com', True), primary('Continue with email')], 12, name='Email'),
                note('New or existing account, same door. Google opens your browser; email stays here.'),
                rich('body-small', f'By signing in you agree to the {inline_link("Terms")} and {inline_link("Privacy Policy")}.', '--text-secondary')]
        return ([head(OFFER_HEAD), note(OFFER_DETAIL)] if title else []) + tail
    if state == 'waiting':
        return [row([icon('refresh-cw', '--text-primary', 24), head('Finish signing in in your browser.')], 8),
                note('The app continues on its own once the browser is done.'),
                rich('body-small', f'Nothing happened? {inline_link("Open the browser again")}', '--text-secondary'),
                link_row(['Use an email code instead'])]
    if state == 'signed-in':
        return [head(f'Signed in as {EMAIL} · 500 credits')]
    if state.startswith('choose'):
        wrong = state == 'choose-wrong-password'
        out = [head('How do you want to sign in?'), rich('body-small', f'{EMAIL}. {inline_link("Change email")}', '--text-secondary'),
               f'<div style="{BOX}align-self:stretch;margin-top:var(--space-8);display:flex">{primary("Email me a 6-digit code", block=True)}</div>',
               note('New here? The code makes your account.'), or_rule(),
               row([field('••••••••••' if wrong else 'Password', not wrong), secondary('Sign in')], 12, name='Password')]
        return out + ([error('That password is wrong.')] if wrong else []) + [link_row(['Forgot password'])]
    sent = [head('Check your email.'), note(f'We sent a 6-digit code to {EMAIL}.')]
    if state == 'code':
        return sent + [code_cells('481', active=3), note('The sixth digit signs you in. Read the email on any device.'),
                       link_row(['Send a new code', 'Change email', 'Use the browser instead'])]
    if state == 'code-wrong':
        return sent + [code_cells(refused=True), error('That code is wrong.'), link_row(['Send a new code', 'Change email', 'Use the browser instead'])]
    return sent + [code_cells('481920', refused=True), error('That code no longer works. We can send a new one.'),
                   row([primary('Send a new code'), link_row(['Change email', 'Use the browser instead'], cancel=False)], 12, justify='space-between')]

def offer_card(state=None):
    """The first door's card (.onboarding-offer) in each state of the sign-in."""
    return f'<div data-n="Door: sign in" style="{BOX}align-self:stretch;display:flex;flex-direction:column;gap:var(--space-4);align-items:flex-start;padding:var(--space-16);{OFFER_BOX}">{"".join(sign_in_door(state))}</div>'

def doors(state=None):
    """The free doors stay open while the person signs in; they close once a sign-in finished here, until the controller moves on."""
    dim = state == 'signed-in'
    just = f'<div style="{BOX}padding:var(--space-4) 0">' + text('label-bold', 'Just slice for now', '--action-disabled-text' if dim else '--action-primary', 'flex:none', True) + '</div>'
    return col([text('label', DOORS_LABEL, '--text-secondary'), offer_card(state), free_door('Your own API key', 'Free', dim), free_door('Claude Code or Claude Desktop', 'Free · MCP server', dim), just], 8, name='Doors')

tools.description:
Open the Browser pane: pass `url` to open a browser tab at a URL (no dev server needed — use this for external sites, staging, docs, or your deployed app), OR pass `name` to start a dev server from .claude/launch.json.

Start a dev server by name from .claude/launch.json. If .claude/launch.json doesn't exist, create it first with this format:
{
  "version": "0.0.1",
  "configurations": [
    {
      "name": "<unique-name>",
      "runtimeExecutable": "<command>",
      "runtimeArgs": ["<args>"],
      "port": <port>
    }
  ]
}
Set "runtimeExecutable" to the command (e.g. "npm"), "runtimeArgs" to the arguments (e.g. ["run", "dev"]), and "port" to the server port. An optional "url" (http/https) opens the preview there instead of http://localhost:<port>. A localhost "url" must be just the server's origin — no path or query, matching the entry's port — for example "https://localhost:8443" or "http://app.localhost:3000"; to show a specific page, navigate after the preview opens. Non-localhost URLs may carry paths and are subject to the user's permission and the organization's browsing policy. A configuration with "url" and no command attaches to an already-running server. Only include servers you actually need to preview. Reuses the server if already running. ALWAYS use this instead of Bash for running servers. If the deliverable is already published as an Artifact, update the Artifact instead of starting a server to show it.

