diff --git a/src/slic3r/GUI/JusPrin/HomeUI/src/styles.css b/src/slic3r/GUI/JusPrin/HomeUI/src/styles.css
index 2fa9c6e42c..bfa5af17cf 100644
--- a/src/slic3r/GUI/JusPrin/HomeUI/src/styles.css
+++ b/src/slic3r/GUI/JusPrin/HomeUI/src/styles.css
@@ -589,6 +589,42 @@ body {
   justify-content: center;
 }

+/* The sign-in door's paragraphs, which the welcome's .onboarding reset
+   does not reach here; the card's gap spaces them. */
+.agent-card p {
+  margin: 0;
+}
+
+/* The column is too narrow for a field beside its button: the button goes
+   under the field, each the card's width. */
+.agent-card .onboarding-email-row {
+  flex-direction: column;
+}
+
+/* Six full-size code cells are wider than the column: they share its width
+   and stay square. */
+.agent-card .code-cell {
+  flex: 1 1 0;
+  width: auto;
+  height: auto;
+  aspect-ratio: 1;
+}
+
+/* The links wrap here; without the dots a wrapped line does not start with one. */
+.agent-card .onboarding-links {
+  column-gap: 12px;
+}
+
+.agent-card .onboarding-link-dot {
+  display: none;
+}
+
+/* A spent code's "Send a new code" takes the card's width, its links under it. */
+.agent-card .onboarding-new-code-row {
+  flex-direction: column;
+  align-items: stretch;
+}
+
 .agent-card-heading {
   font: var(--font-body-bold);
 }
